from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    """
    Abstract base class for sorting algorithms.
    """

    def __init__(self):
        pass

    @abstractmethod
    def sort(self, data):
        pass

    def swap(self, a, b):
        pass

class BubbleSort(SortAlgorithm):
    """
    Implementation of Bubble Sort algorithm.
    """
    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n-i-1):
                if data[j] > data[j+1]:
                    data[j], data[j+1] = data[j+1], data[j]

    def swap(self, a, b):
        data[a], data[b] = data[b], data[a]

class SelectionSort(SortAlgorithm):
    """
    Implementation of Selection Sort algorithm.
    """
    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_index = i
            for j in range(i+1, n):
                if data[j] < data[min_index]:
                    min_index = j
            data[i], data[min_index] = data[min_index], data[i]

    def swap(self, a, b):
        data[a], data[b] = data[b], data[a]

def test_sort_algorithms():
    """
    Tests the SortAlgorithm classes.
    """
    # Bubble Sort
    bubble_sort = BubbleSort()
    data = [5, 2, 8, 1, 9]
    bubble_sort.sort(data)
    print("Bubble Sort sorted:", data)

    # Selection Sort
    selection_sort = SelectionSort()
    data = [5, 2, 8, 1, 9]
    selection_sort.sort(data)
    print("Selection Sort sorted:", data)

    # Empty array test
    empty_array = []
    bubble_sort.sort(empty_array)
    print("Bubble Sort empty array:", empty_array)
    selection_sort.sort(empty_array)
    print("Selection Sort empty array:", empty_array)
